# Subset Sum Problem: Can we achieve a sum of 638 using numbers 1 through 50?
target = 638
cards = list(range(1, 51))

# Initialize DP array: dp[j] is True if sum j is achievable
dp = [False] * (target + 1)
dp[0] = True

for card in cards:
    # Iterate backwards to avoid using the same card multiple times in one step
    for j in range(target, card - 1, -1):
        if dp[j - card]:
            dp[j] = True

if dp[target]:
    print(f"Target sum {target} is achievable.")
else:
    print(f"Target sum {target} is NOT achievable.")

